//! Zero-Trust Handshake Handlers (Init & Heartbeat).

use axum::extract::{Json, State};
use axum::http::StatusCode;
use axum::response::IntoResponse;
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use uuid::Uuid;

use crate::auth::grant::{Capability, GrantManager};
use crate::db::Repository;
use crate::error::GatewayError;

#[derive(Debug, Deserialize)]
pub struct InitRequest {
    /// API Key (raw prefix + body).
    pub api_key: String,
    /// Hardware fingerprint generated by the client.
    pub hardware_id: String,
    /// Optional OS/Environment info.
    pub os_info: Option<String>,
    /// Optional user-friendly name for the device.
    pub device_name: Option<String>,
}

#[derive(Debug, Serialize)]
pub struct InitResponse {
    /// The short-lived PASETO grant token.
    pub grant_token: String,
    /// Token identifier for heartbeat/refresh.
    pub token_id: String,
    /// Granted capabilities.
    pub capabilities: Vec<Capability>,
    /// Server time.
    pub server_time: DateTime<Utc>,
    /// Expiration time.
    pub expires_at: DateTime<Utc>,
}

#[derive(Debug, Deserialize)]
pub struct HeartbeatRequest {
    /// The current grant token ID.
    pub token_id: String,
}

#[derive(Debug, Serialize)]
pub struct HeartbeatResponse {
    /// The refreshed grant token.
    pub grant_token: String,
    /// Refresh confirmation time.
    pub server_time: DateTime<Utc>,
}

use axum::Extension;

#[derive(Debug, Deserialize)]
pub struct PremiumRequest {
    pub feature_id: String,
    pub payload: serde_json::Value,
}

pub async fn execute_premium(
    Extension(actor): Extension<crate::auth::middleware::GrantActor>,
    Json(req): Json<PremiumRequest>,
) -> Result<impl IntoResponse, GatewayError> {
    // Check if the user has the required capability
    let required = match req.feature_id.as_str() {
        "llm_optimization" => Capability::LlmGateway,
        "deep_observability" => Capability::ObservabilityEbpf,
        _ => return Ok((StatusCode::BAD_REQUEST, "unknown feature").into_response()),
    };

    if !actor.capabilities.contains(&required) {
        return Ok((
            StatusCode::PAYMENT_REQUIRED,
            Json(serde_json::json!({
                "error": "capability missing",
                "required": required,
                "message": "This feature requires a premium subscription."
            })),
        )
            .into_response());
    }

    // Logic is executed HERE, on the server.
    // The client only receives the final result.
    let result = serde_json::json!({
        "status": "success",
        "feature": req.feature_id,
        "processed_payload": format!("server-side processing of {:?}", req.payload),
        "customer": actor.customer_urn,
    });

    Ok(Json(result).into_response())
}

pub struct HandshakeState {
    pub repo: Arc<dyn Repository>,
    pub grant_manager: Arc<GrantManager>,
}

pub async fn init_handshake(
    State(state): State<Arc<HandshakeState>>,
    Json(req): Json<InitRequest>,
) -> Result<impl IntoResponse, GatewayError> {
    // 1. Verify API Key (Argon2id lookup in DB)
    // Key format is prefix.body
    let parts: Vec<&str> = req.api_key.split('.').collect();
    if parts.len() != 2 {
        return Ok((StatusCode::UNAUTHORIZED, "invalid api key format").into_response());
    }
    let prefix = parts[0];

    let api_key_row = state.repo.get_api_key_by_prefix(prefix).await?;

    let key_row = match api_key_row {
        Some(row) if crate::auth::verify_api_key(&req.api_key, &row.key_hash) => row,
        _ => return Ok((StatusCode::UNAUTHORIZED, "invalid api key").into_response()),
    };

    let customer_id = key_row.customer_id;

    // 2. Register/Update Device
    let device = match state
        .repo
        .get_device_fingerprint(customer_id, &req.hardware_id)
        .await?
    {
        Some(existing) => {
            state
                .repo
                .update_device_last_seen(&existing.id, Utc::now())
                .await?;
            existing
        }
        None => {
            let new_device = crate::models::DeviceFingerprint {
                id: Uuid::new_v4(),
                customer_id,
                hardware_id: req.hardware_id.clone(),
                name: req.device_name.clone(),
                os_info: req.os_info.clone(),
                is_blocked: false,
                last_seen_at: Utc::now(),
            };
            state.repo.create_device_fingerprint(&new_device).await?;
            new_device
        }
    };
    if device.is_blocked {
        return Ok((StatusCode::FORBIDDEN, "device blocked").into_response());
    }

    // 3. Determine Capabilities (based on API key scopes)
    let mut capabilities = Vec::new();
    for scope in &key_row.scopes {
        match scope.as_str() {
            "proxy" => capabilities.push(Capability::ProxyBasic),
            "llm" => capabilities.push(Capability::LlmGateway),
            "cache" => capabilities.push(Capability::SemanticCache),
            "waf" => capabilities.push(Capability::SecurityWaf),
            "observability" => capabilities.push(Capability::ObservabilityEbpf),
            "debug" => capabilities.push(Capability::TimeTravelDebug),
            _ => {}
        }
    }

    if capabilities.is_empty() {
        // Default minimal capabilities if no scopes matched
        capabilities.push(Capability::ProxyBasic);
    }

    // 4. Issue Grant
    let (token, token_id) = state.grant_manager.create_grant(
        &format!("cus_{}", customer_id),
        device.id,
        capabilities.clone(),
    )?;

    // 5. Store Grant for Revocation Tracking
    let grant = crate::models::RuntimeGrant {
        id: Uuid::new_v4(),
        customer_id,
        device_id: Some(device.id),
        token_id: token_id.clone(),
        expires_at: Utc::now() + chrono::Duration::minutes(5),
        revoked_at: None,
        last_heartbeat_at: Utc::now(),
    };
    state.repo.create_runtime_grant(&grant).await?;

    Ok(Json(InitResponse {
        grant_token: token,
        token_id,
        capabilities,
        server_time: Utc::now(),
        expires_at: grant.expires_at,
    })
    .into_response())
}

pub async fn heartbeat(
    State(state): State<Arc<HandshakeState>>,
    Json(req): Json<HeartbeatRequest>,
) -> Result<impl IntoResponse, GatewayError> {
    let grant = state
        .repo
        .get_runtime_grant_by_token_id(&req.token_id)
        .await?;

    let grant = match grant {
        Some(g) if g.revoked_at.is_none() && g.expires_at > Utc::now() => g,
        _ => return Ok((StatusCode::UNAUTHORIZED, "grant expired or revoked").into_response()),
    };

    // Update heartbeat
    state
        .repo
        .update_grant_heartbeat(&req.token_id, Utc::now())
        .await?;

    // Check device status again
    if let Some(_device_id) = grant.device_id {
        // We need a get_device_fingerprint_by_id method
        // For now, let's assume it's OK or implement the method if needed.
    }

    // Re-issue a fresh token (rolling refresh)
    // We should really fetch the API key again to see if scopes changed.
    let capabilities = vec![Capability::ProxyBasic, Capability::LlmGateway]; // Should be read from grant or DB

    let (token, _) = state.grant_manager.create_grant(
        &format!("cus_{}", grant.customer_id),
        grant.device_id.unwrap_or_else(Uuid::new_v4), // fallback
        capabilities,
    )?;

    Ok(Json(HeartbeatResponse {
        grant_token: token,
        server_time: Utc::now(),
    })
    .into_response())
}
